1	// Acceptance test for the change request:
2	//   "Invoices should move through stages. First a draft. Then I send it. Then it gets paid. Keep a
3	//    record when I send one. Only let me take payment once it has been sent."
4	//
5	// An invoice moves through three stages: DRAFT → SENT → PAID. On a project's detail page each invoice
6	// shows its stage (invoice-status). While it is a DRAFT it offers a control to send it
7	// (invoice-send-<id>) and NO control to take payment — payment is only offered once it has been SENT
8	// (invoice-pay-<id>). Sending flips the stage to SENT, persists across a fresh load, and — because
9	// the request wants a record kept when one is sent — appends exactly one audit record
10	// `INVOICE_SENT id=<id> amount=<amount>` per send. A newly created invoice starts as a DRAFT.
11	//
12	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
13	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients` honours
14	// { id, name, email }, `projects` honours { id, name, clientId } and `invoices` honours
15	// { id, amount, projectId, status }.
16	import { test, expect, type Page, type Locator } from '@playwright/test';
17	import { resetAndSeed } from '../support/seed';
18	import { auditLines } from '../support/audit';
19	
20	// Each stage's status cell is matched by the WORD that names the stage, case-insensitively, so the
21	// test binds to the MEANING and not one capitalisation ("Draft"/"DRAFT"/"draft" all count). The word
22	// boundaries keep the three stages distinct from one another.
23	const DRAFT = /\bdraft\b/i;
24	const SENT = /\bsent\b/i;
25	const PAID = /\bpaid\b/i;
26	
27	const invoiceRows = (page: Page) => page.locator('[data-testid^="invoice-row-"]');
28	const statusOf = (page: Page, id: number): Locator =>
29	  page.getByTestId(`invoice-row-${id}`).getByTestId('invoice-status');
30	
31	// The audit records. The amount may be written bare (100) or with scale (100.00), so accept an
32	// optional fractional part; everything else is matched exactly.
33	const sentRecord = (id: number, amount: number) =>
34	  new RegExp(`^INVOICE_SENT id=${id} amount=${amount}(\\.\\d+)?$`);
35	const paidRecord = (id: number, amount: number) =>
36	  new RegExp(`^INVOICE_PAID id=${id} amount=${amount}(\\.\\d+)?$`);
37	
38	const linesMatching = (re: RegExp): string[] => auditLines().filter((line) => re.test(line));
39	
40	test.describe('Invoices move through stages: draft → sent → paid', () => {
41	  test('a draft offers a send control but no payment control until it has been sent', async ({
42	    page,
43	  }) => {
44	    await resetAndSeed({
45	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
46	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
47	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'DRAFT' }],
48	    });
49	
50	    await page.goto('/projects/1');
51	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
52	
53	    // It starts as a draft: it offers a send control, and does NOT yet offer a way to take payment.
54	    await expect(statusOf(page, 1)).toHaveText(DRAFT);
55	    const send = page.getByTestId('invoice-send-1');
56	    await expect(send).toBeVisible();
57	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
58	
59	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
60	    // send (not the seeding) wrote it.
61	    expect(auditLines()).toEqual([]);
62	
63	    await send.click();
64	
65	    // The stage is now SENT: the send control is gone (it has already been sent) and a payment
66	    // control is now offered.
67	    await expect(statusOf(page, 1)).toHaveText(SENT);
68	    await expect(statusOf(page, 1)).not.toHaveText(PAID);
69	    await expect(page.getByTestId('invoice-send-1')).toHaveCount(0);
70	    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();
71	
72	    // Exactly one record was kept for this send, carrying the invoice's id and amount.
73	    expect(linesMatching(sentRecord(1, 100))).toHaveLength(1);
74	    expect(auditLines()).toHaveLength(1);
75	
76	    // The SENT stage is held by the server, not just the page: it survives a fresh load, still
77	    // offering payment and not a second send, and reloading does not record the send again.
78	    await page.reload();
79	    await expect(statusOf(page, 1)).toHaveText(SENT);
80	    await expect(page.getByTestId('invoice-send-1')).toHaveCount(0);
81	    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();
82	    expect(linesMatching(sentRecord(1, 100))).toHaveLength(1);
83	    expect(auditLines()).toHaveLength(1);
84	  });
85	
86	  test('sending one invoice records it and leaves the others as drafts', async ({ page }) => {
87	    await resetAndSeed({
88	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
89	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
90	      invoices: [
91	        { id: 1, amount: 100, projectId: 1, status: 'DRAFT' },
92	        { id: 2, amount: 250, projectId: 1, status: 'DRAFT' },
93	      ],
94	    });
95	
96	    await page.goto('/projects/1');
97	    await expect(invoiceRows(page)).toHaveCount(2);
98	
99	    // Both start as drafts: each offers a send control and neither offers payment.
100	    await expect(page.getByTestId('invoice-send-1')).toBeVisible();
101	    await expect(page.getByTestId('invoice-send-2')).toBeVisible();
102	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
103	    await expect(page.getByTestId('invoice-pay-2')).toHaveCount(0);
104	
105	    // Send the first invoice.
106	    await page.getByTestId('invoice-send-1').click();
107	
108	    // Only that invoice advanced: it is SENT and now offers payment; its sibling is still a draft
109	    // offering only a send control.
110	    await expect(statusOf(page, 1)).toHaveText(SENT);
111	    await expect(page.getByTestId('invoice-pay-1')).toBeVisible();
112	    await expect(statusOf(page, 2)).toHaveText(DRAFT);
113	    await expect(page.getByTestId('invoice-send-2')).toBeVisible();
114	    await expect(page.getByTestId('invoice-pay-2')).toHaveCount(0);
115	
116	    // Exactly one record so far, for the invoice that was sent.
117	    expect(linesMatching(sentRecord(1, 100))).toHaveLength(1);
118	    expect(auditLines()).toHaveLength(1);
119	
120	    // Send the second invoice too — a record is kept for it as well.
121	    await page.getByTestId('invoice-send-2').click();
122	    await expect(statusOf(page, 2)).toHaveText(SENT);
123	
124	    expect(linesMatching(sentRecord(1, 100))).toHaveLength(1);
125	    expect(linesMatching(sentRecord(2, 250))).toHaveLength(1);
126	    expect(auditLines()).toHaveLength(2);
127	  });
128	
129	  test('an invoice moves draft → sent → paid, keeping a record at each step', async ({ page }) => {
130	    await resetAndSeed({
131	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
132	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
133	      invoices: [{ id: 1, amount: 100, projectId: 1, status: 'DRAFT' }],
134	    });
135	
136	    await page.goto('/projects/1');
137	
138	    // Draft: can be sent, cannot yet be paid.
139	    await expect(statusOf(page, 1)).toHaveText(DRAFT);
140	    await expect(page.getByTestId('invoice-send-1')).toBeVisible();
141	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
142	
143	    // Send it: now SENT and payable, with one send record kept.
144	    await page.getByTestId('invoice-send-1').click();
145	    await expect(statusOf(page, 1)).toHaveText(SENT);
146	    const pay = page.getByTestId('invoice-pay-1');
147	    await expect(pay).toBeVisible();
148	    expect(linesMatching(sentRecord(1, 100))).toHaveLength(1);
149	    expect(auditLines()).toHaveLength(1);
150	
151	    // Pay it: now PAID, offering neither control, with a payment record kept alongside the send one.
152	    await pay.click();
153	    await expect(statusOf(page, 1)).toHaveText(PAID);
154	    await expect(page.getByTestId('invoice-send-1')).toHaveCount(0);
155	    await expect(page.getByTestId('invoice-pay-1')).toHaveCount(0);
156	    expect(linesMatching(paidRecord(1, 100))).toHaveLength(1);
157	
158	    // Both steps were recorded, in the order they happened: sent first, then paid.
159	    const lines = auditLines();
160	    expect(lines).toHaveLength(2);
161	    expect(lines[0]).toMatch(sentRecord(1, 100));
162	    expect(lines[1]).toMatch(paidRecord(1, 100));
163	
164	    // The PAID stage is held by the server and survives a fresh load without recording anything more.
165	    await page.reload();
166	    await expect(statusOf(page, 1)).toHaveText(PAID);
167	    expect(auditLines()).toHaveLength(2);
168	  });
169	
170	  test('a newly created invoice starts as a draft that must be sent before it can be paid', async ({
171	    page,
172	  }) => {
173	    await resetAndSeed({
174	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
175	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
176	      invoices: [],
177	    });
178	
179	    await page.goto('/projects/1');
180	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
181	    await expect(invoiceRows(page)).toHaveCount(0);
182	
183	    // Add a new invoice by giving it an amount.
184	    await page.getByTestId('invoice-form-amount').fill('300');
185	    await page.getByTestId('invoice-form-submit').click();
186	
187	    // Its id is assigned by the server, so find the new row by the amount it carries and read its id.
188	    const addedRow = invoiceRows(page).filter({
189	      has: page.getByTestId('invoice-amount').getByText('300', { exact: false }),
190	    });
191	    await expect(addedRow).toHaveCount(1);
192	    const rowTestId = await addedRow.getAttribute('data-testid');
193	    const id = Number(rowTestId!.replace('invoice-row-', ''));
194	
195	    // "First a draft": the new invoice is a draft — it offers a send control and no payment control.
196	    await expect(addedRow.getByTestId('invoice-status')).toHaveText(DRAFT);
197	    await expect(page.getByTestId(`invoice-send-${id}`)).toBeVisible();
198	    await expect(page.getByTestId(`invoice-pay-${id}`)).toHaveCount(0);
199	
200	    // Merely creating a draft records nothing — the record is kept when it is SENT, not when raised.
201	    expect(auditLines()).toEqual([]);
202	  });
203	
204	  test('an invoice already sent is payable with no send control; a paid one offers neither', async ({
205	    page,
206	  }) => {
207	    await resetAndSeed({
208	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
209	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
