43	
44	// A quantity is a bare count; a price, a line amount or the total may be rendered as money ($300.00)
45	// or bare (300). Assert the figure it carries is PRESENT, so the test binds to the value and not to
46	// one presentation. Figures in each test are chosen so no value is a substring of another.
47	async function expectValue(cell: Locator, n: number): Promise<void> {
48	  await expect(cell).toContainText(String(n));
